import React from 'react';
import { Link } from 'react-router-dom';

const Inicio = () => (
  <div className="container">
    <h1>PHG Soluciones Contables</h1>
    <p>Tu aliado en servicios contables, auditoría y asesoría financiera.</p>
    <nav>
      <Link to="/servicios">Servicios</Link>
      <Link to="/sobre-nosotros">Sobre Nosotros</Link>
      <Link to="/contacto">Contacto</Link>
      <Link to="/ubicacion-redes">Ubicación y Redes</Link>
    </nav>
    <img src="/logo.png" alt="PHG Soluciones Contables" style={{maxWidth:'200px',marginTop:'2rem'}} />
  </div>
);

export default Inicio;
